 static int errorCopy(String value){String code=value==null?"":value.toLowerCase(java.util.Locale.ROOT);if(code.contains("account_unavailable"))return R.string.permissions_account_unavailable;if(code.matches(".*(adoption|request|listing|case|notice)_unavailable.*"))return R.string.lc_error_record_unavailable;if(code.contains("network")||code.equals("unavailable"))return R.string.lc_error_network;if(code.contains("rate_limited")||code.contains("quota"))return R.string.lc_error_rate;if(code.contains("unauthenticated")||code.contains("sign in"))return R.string.lc_error_signin;if(code.contains("phone"))return R.string.lc_missing_phone;if(code.contains("email"))return R.string.oc4_email_required;if(code.contains("terms"))return R.string.oc4_terms_required;if(code.contains("listing_requirements"))return R.string.oc4_listing_required;if(code.contains("display_name"))return R.string.permissions_name_required;if(code.contains("own_listing"))return R.string.lc_error_own_listing;if(code.contains("active_request"))return R.string.lc_error_active_request;if(code.contains("not_published"))return R.string.lc_error_not_published;if(code.contains("answers_required")||code.contains("invalid_intent")||code.contains("invalid_identifier"))return R.string.lc_error_invalid_input;if(code.contains("photo_required")||code.contains("invalid_asset"))return R.string.lc_error_media;if(code.contains("listing_changed")||code.contains("request_changed")||code.contains("adoption_changed")||code.contains("contract_changed")||code.contains("baseline_changed")||code.contains("source_changed")||code.contains("care_changed")||code.contains("identity_changed")||code.contains("conflict"))return R.string.lc_error_changed;if(code.contains("already_selected")||code.contains("pet_reserved"))return R.string.lc_error_reserved;if(code.contains("not_ready")||code.contains("reports_not_reviewed"))return R.string.lc_error_not_ready;if(code.contains("adoption_closed")||code.contains("conversation_closed"))return R.string.lc_error_closed;if(code.contains("host_required"))return R.string.lc_error_host_only;if(code.contains("adopter_required"))return R.string.lc_error_adopter_only;if(code.contains("report_invalid")||code.contains("correction_invalid")||code.contains("review_invalid")||code.contains("baseline_invalid")||code.contains("listing_invalid"))return R.string.lc_error_invalid_input;if(code.contains("restricted"))return R.string.auth_restricted;if(code.contains("account_unavailable"))return R.string.permissions_account_unavailable;if(code.contains("not_participant")||code.contains("permission")||code.contains("denied"))return R.string.permissions_not_participant;if(code.contains("profile"))return R.string.lc_missing_profile;if(code.contains("flow_rollout")||code.contains("flow_not_configured"))return R.string.lc_disabled;return R.string.lc_error_server;}
