 private void cases(){for(Map<String,Object> c:rows(m.data.get("rows")))buttonText(s(R.string.lc_help)+" Â· "+state(str(c.get("state"))),()->m.command("assign",map("adoptionId",c.get("adoptionId")),number(c.get("version"))));if(rows(m.data.get("rows")).isEmpty())text(s(R.string.lc_empty),false);if(m.data.get("next")!=null)button(R.string.social_more,()->m.load("cases",map("kind","cases","after",m.data.get("next"))),false);}
