 private void messages(){for(Map<String,Object> row:rows(m.data.get("rows")))text((m.ticket.uid.equals(row.get("senderUid"))?s(R.string.oc3_you):s(R.string.social_member))+"\n"+str(row.get("body")),false);if(Boolean.TRUE.equals(m.data.get("readOnly"))){text(s(R.string.lc_readonly),false);return;}field("message",R.string.feedback_chat_message,3).setEnabled(!m.busy&&!m.form.containsKey("messageOperation"));button(R.string.lc_send,()->{if(m.busy)return;String op=m.form.computeIfAbsent("messageOperation",k->UUID.randomUUID().toString());String payload=m.form.computeIfAbsent("messagePayload",k->value("message"));m.busy=true;m.changed();AdoptionApi.call("flowSend",map("adoptionId",m.id,"operationId",op,"body",payload)).addOnCompleteListener(t->{if(!m.current()||isDestroyed())return;m.busy=false;if(t.isSuccessful()){m.form.remove("messageOperation");m.form.remove("messagePayload");m.form.remove("message");m.load("messages",map("kind","messages","adoptionId",m.id,"before",null));}else {m.error="pending_reconcile";render();}});},true);if(m.data.get("next")!=null)button(R.string.social_more_comments,()->m.load("messages",map("kind","messages","adoptionId",m.id,"before",m.data.get("next"))),false);button(R.string.lc_refresh,()->m.load("messages",map("kind","messages","adoptionId",m.id,"before",null)),false);}
 private void buttonText(String text,Runnable r){body.addView(SocialSurface.quiet(this,text,r),new LinearLayout.LayoutParams(-1,-2));}
 private void refresh(){switch(m.page){case "index":m.index(m.role,m.cursorPage);break;case "detail":m.detail(m.id);break;case "request":m.load("request",map("kind","request","requestId",m.id));break;case "report":m.load("report",map("kind","report","adoptionId",m.id,"reportId",m.reportId));break;case "messages":m.load("messages",map("kind","messages","adoptionId",m.id,"before",null));break;case "cases":case "notices":m.load(m.page,map("kind",m.page,"after",null));break;case "listing":m.load("listing",map("kind","listing","listingId",m.listing));break;default:m.readiness();}}

 private void back(){if(m.pending()){m.reconcile();return;}if(m.page.equals("revise")||m.page.equals("baseline")||m.page.equals("report")||m.page.equals("messages")){m.detail(m.id);return;}if(m.page.equals("request")||m.page.equals("detail")||m.page.equals("notices")||m.page.equals("cases")){m.index(m.role,m.cursorPage);return;}if(m.page.equals("apply")){m.load("listing",map("kind","listing","listingId",m.listing));return;}finish();}
 private int categoryId(String key){switch(key){case "conditions":return R.string.lc_conditions;case "injuries":return R.string.lc_injuries;case "marks":return R.string.lc_marks;case "vaccinations":return R.string.lc_vaccinations;default:return R.string.lc_treatments;}}private String category(String key){return s(categoryId(key));}private String health(String state){return s(state.equals("KNOWN")?R.string.lc_known:state.equals("NOT_ASSESSED")?R.string.lc_not_assessed:R.string.lc_unknown);}
 private String state(String st){String[] codes={"CONTRACT_PENDING","CONTRACT_ACCEPTED","BASELINE_PENDING","HANDOVER_PENDING","MONITORING","FINALIZED"};for(int i=0;i<codes.length;i++)if(codes[i].equals(st))return getResources().getStringArray(R.array.lc_states)[i];switch(st){case "SUBMITTED":return s(R.string.oc4_status_submitted);case "REVIEWED":return s(R.string.lc_reviewed);case "PENDING":return s(R.string.lc_wait);case "OVERDUE":return "QuÃ¡ háº¡n cáº­p nháº­t";case "EXTENDED_MONITORING":return s(R.string.lc_extend);case "RETURN_RECOMMENDED":return s(R.string.lc_return_recommended);case "RETURN_IN_PROGRESS":return s(R.string.lc_return_progress);case "RETURNED":return s(R.string.lc_returned);case "CANCELLED":case "CANCELLED_BEFORE_HANDOVER":return s(R.string.oc4_status_cancelled);case "REJECTED":return s(R.string.oc4_status_rejected);case "WITHDRAWN":return s(R.string.oc4_status_withdrawn);case "ACCEPTED":return s(R.string.oc4_status_selected);default:return s(R.string.lc_help);}}
 private String date(Object v){try{if(v instanceof Map){Object seconds=((Map<?,?>)v).get("_seconds");return java.text.DateFormat.getDateInstance().format(new Date(((Number)seconds).longValue()*1000));}return java.text.DateFormat.getDateInstance().format(Date.from(java.time.Instant.parse(str(v))));}catch(Exception ignored){return "";}}
